  1→import {
  2→  ChangeDetectionStrategy,
  3→  Component,
  4→  OnInit,
  5→  OnDestroy,
  6→  computed,
  7→  effect,
  8→  inject,
  9→  signal,
 10→} from "@angular/core";
 11→import { ButtonDirective } from "@aspect/ui";
 12→import { ActivatedRoute, Router } from "@angular/router";
 13→import { ClockDisplayComponent } from "../../shared/clock-display.component";
 14→import { PhaseBadgeComponent } from "../../shared/phase-badge.component";
 15→import { AmbientBackgroundComponent } from "../../shared/ambient-background.component";
 16→import { BriefingOverlayComponent } from "../../shared/briefing-overlay.component";
 17→import { CompletionOverlayComponent } from "../../shared/completion-overlay.component";
 18→import {
 19→  resolvePlayerRole,
 20→  submitRoleRecommendation,
 21→  submitDecision,
 22→} from "./player-decision-handlers";
 23→import { LogsDrawerComponent } from "../../shared/logs-drawer.component";
 24→import { StressBarComponent } from "../../shared/stress-bar.component";
 25→import { DomainService } from "../../core/domain.service";
 26→import { EngineApiService } from "../../core/engine-api.service";
 27→import { ExerciseWsService } from "../../core/exercise-ws.service";
 28→import { ExerciseStore } from "../../core/exercise.store";
 29→import { TickService } from "../../core/tick.service";
 30→import { DecisionApiService } from "../../core/decision-api.service";
 31→import { Subscription } from "rxjs";
 32→import { handlePlayerWsMessage } from "./player-ws-handler";
 33→import { RoleCardComponent } from "./role-card.component";
 34→import { SystemStatusBoardComponent } from "../../shared/system-status-board.component";
 35→import { WarfareDomainBoardComponent } from "../../shared/warfare-domain-board.component";
 36→import type { RoleCardSubmission } from "./role-card.component";
 37→import { buildRoleCards } from "./role-card.types";
 38→
 39→@Component({
 40→  selector: "tfc-player-view",
 41→  changeDetection: ChangeDetectionStrategy.OnPush,
 42→  providers: [ExerciseStore, TickService],
 43→  imports: [
 44→    ClockDisplayComponent,
 45→    PhaseBadgeComponent,
 46→    AmbientBackgroundComponent,
 47→    BriefingOverlayComponent,
 48→    CompletionOverlayComponent,
 49→    LogsDrawerComponent,
 50→    StressBarComponent,
 51→    ButtonDirective,
 52→    RoleCardComponent,
 53→    SystemStatusBoardComponent,
 54→    WarfareDomainBoardComponent,
 55→  ],
 56→  templateUrl: "./player-view.html",
 57→})
 58→export class PlayerView implements OnInit, OnDestroy {
 59→  protected readonly store = inject(ExerciseStore);
 60→  protected readonly domain = inject(DomainService);
 61→  private readonly api = inject(EngineApiService);
 62→  private readonly decisionApi = inject(DecisionApiService);
 63→  protected readonly logsOpen = signal(false);
 64→  private readonly ws = inject(ExerciseWsService);
 65→  private readonly router = inject(Router);
 66→  private readonly route = inject(ActivatedRoute);
 67→  protected readonly roleLabel = signal("Advisor");
 68→  protected readonly beginningExercise = signal(false);
 69→  private readonly exerciseId = signal(1);
 70→  private readonly participantId = signal("");
 71→  private readonly tick = inject(TickService);
 72→  private snapshotLoaded = false;
 73→  private sub: Subscription | null = null;
 74→  private connSub: Subscription | null = null;
 75→
 76→  protected readonly activeDecisions = computed(() => {
 77→    const role = this.store.playerRole();
 78→    return this.store.openDecisions().filter((d) => {
 79→      if (!d.target_roles || d.target_roles.length === 0) return true;
 80→      if (
 81→        role === "all_roles" ||
 82→        role === "all_advisors" ||
 83→        role === "solo_player" ||
 84→        role === "decision_maker"
 85→      )
 86→        return true;
 87→      return d.target_roles.includes(role);
 88→    });
 89→  });
 90→
 91→  protected readonly isMultiRole = computed(() => {
 92→    const role = this.store.playerRole();
 93→    return (
 94→      role === "all_advisors" || role === "solo_player" || role === "all_roles"
 95→    );
 96→  });
 97→
 98→  protected readonly submittedRoles = signal<Set<string>>(new Set());
 99→
100→  protected readonly currentTurnEvent = computed(() => {
101→    const decisions = this.activeDecisions();
102→    if (decisions.length === 0) return null;
103→    const decision = decisions[0];
104→    if (!decision.event_id) return null;
105→    return this.store.events().find((e) => e.id === decision.event_id) ?? null;
106→  });
107→
108→  protected readonly roleCards = computed(() => {
109→    const allRoles = this.store.context()?.roles ?? [];
110→    const event = this.currentTurnEvent();
111→    const decision = this.activeDecisions()[0] ?? null;
112→    const role = this.store.playerRole();
113→    const multiRole = this.isMultiRole();
114→    const playerRoleDef = allRoles.find((r) => r.id === role);
115→    const showDecisionMaker =
116→      role === "all_roles" ||
117→      role === "solo_player" ||
118→      role === "decision_maker" ||
119→      this.store.isPracticeMode() ||
120→      playerRoleDef?.player_type === "decision_maker";
121→    // Single-role players see only their own role card.
122→    // "decision_maker" URL param maps to the CO role (player_type === "decision_maker").
123→    let roles: typeof allRoles;
124→    if (multiRole) {
125→      roles = allRoles;
126→    } else if (role === "decision_maker") {
127→      roles = allRoles.filter((r) => r.player_type === "decision_maker");
128→    } else {
129→      roles = allRoles.filter((r) => r.id === role);
130→    }
131→    return buildRoleCards(
132→      roles,
133→      event,
134→      decision,
135→      this.submittedRoles(),
136→      showDecisionMaker,
137→      allRoles,
138→    );
139→  });
140→
141→  private _lastDecisionId: string | null = null;
142→  private readonly resetSubmittedRolesEffect = effect(() => {
143→    const id = this.activeDecisions()[0]?.id ?? null;
144→    // Only reset when the decision ID actually changes (not on every WS push)
145→    if (id && id !== this._lastDecisionId) {
146→      this._lastDecisionId = id;
147→      this.submittedRoles.set(new Set());
148→    }
149→  });
150→
151→  // Turn advancement is backend-driven: closing a decision triggers the
152→  // next event in sequence automatically via engine.force_trigger_next_decision.
153→
154→  ngOnInit(): void {
155→    const params = this.route.snapshot.queryParams;
156→    const id = Number(params["exerciseId"] ?? 1);
157→    const pId = String(params["participantId"] ?? "");
158→    const role = String(params["role"] ?? "player");
159→    const gameMode = String(params["gameMode"] ?? "");
160→    this.exerciseId.set(id);
161→    this.participantId.set(pId);
162→    this.store.setParticipantId(pId);
163→    this.store.setPlayerRole(role);
164→    if (gameMode) {
165→      this.store.setGameMode(gameMode);
166→    }
167→    const practiceMode = params["practiceMode"] === "true";
168→    this.store.setPracticeMode(practiceMode);
169→    this.ws.connect(id, "player", pId || undefined);
170→    this.sub = this.ws.messages$.subscribe((msg) =>
171→      handlePlayerWsMessage(
172→        msg,
173→        this.store,
174→        () => this.onExerciseStopped(),
175→        this.ws,
176→      ),
177→    );
178→    this.loadSnapshot(id);
179→    this.decisionApi.getContext(id).subscribe({
180→      next: (ctx) =>
181→        resolvePlayerRole(ctx, role, gameMode, this.store, this.roleLabel),
182→      error: () => {},
183→    });
184→    this.decisionApi.getEngineDecisions(id).subscribe({
185→      next: (decisions) => this.store.applyDecisions(decisions),
186→      error: () => {},
187→    });
188→    this.connSub = this.ws.connected$.subscribe((connected) => {
189→      if (connected && this.snapshotLoaded) this.loadSnapshot(id);
190→    });
191→    this.tick.start(this.store);
192→  }
193→
194→  private loadSnapshot(exerciseId: number): void {
195→    this.api.snapshot(exerciseId).subscribe({
196→      next: (snap) => {
197→        this.snapshotLoaded = true;
198→        this.store.applySnapshot(snap);
199→      },
200→      error: () => this.store.setError("Failed to load snapshot"),
201→    });
202→  }
203→
204→  protected onBeginExercise(): void {
205→    this.beginningExercise.set(true);
206→    this.api.begin(this.exerciseId()).subscribe({
207→      next: (change) => {
208→        this.store.applyPhaseChange(change.phase);
209→        this.store.applyTimeUpdate(change.time);
210→        this.beginningExercise.set(false);
211→      },
212→      error: () => {
213→        this.store.setError("Failed to begin exercise");
214→        this.beginningExercise.set(false);
215→      },
216→    });
217→  }
218→
219→  protected onStop(): void {
220→    this.api.stop(this.exerciseId()).subscribe({
221→      next: () => this.onExerciseStopped(),
222→    });
223→  }
224→
225→  protected onExerciseStopped(): void {
226→    this.ws.disconnect();
227→    this.router.navigate(["/"]);
228→  }
229→
230→  ngOnDestroy(): void {
231→    this.tick.stop();
232→    this.ws.disconnect();
233→    this.sub?.unsubscribe();
234→    this.connSub?.unsubscribe();
235→  }
236→  protected onRoleCardSubmitted(submission: RoleCardSubmission): void {
237→    const decision = this.activeDecisions()[0];
238→    if (!decision) return;
239→    const role = this.store
240→      .context()
241→      ?.roles?.find((r) => r.id === submission.roleId);
242→    if (role?.player_type === "decision_maker") {
243→      submitDecision(
244→        this.decisionApi,
245→        this.store,
246→        this.exerciseId(),
247→        decision,
248→        submission,
249→      );
250→    } else {
251→      submitRoleRecommendation(
252→        this.decisionApi,
253→        this.exerciseId(),
254→        decision,
255→        this.participantId(),
256→        {
257→          roleId: submission.roleId,
258→          selectedOptions: submission.selectedOptions,
259→          freeText: submission.freeText,
260→        },
261→      );
262→    }
263→    const updated = new Set(this.submittedRoles());
264→    updated.add(submission.roleId);
265→    this.submittedRoles.set(updated);
266→  }
267→}
