 1→// apps/tfc/frontend/src/app/features/player/role-card.types.ts
 2→import type { ActiveDecision } from "../../core/decision-api.service";
 3→import type { RoleDef } from "../../core/scenario-api.service";
 4→import type { EventSnapshot } from "../../core/generated/state-changes.types";
 5→
 6→/** Extract the roleId from a recommendation key ("participantId:roleId" or bare "roleId"). */
 7→export function extractRecRoleId(key: string): string {
 8→  const colonIdx = key.indexOf(":");
 9→  return colonIdx !== -1 ? key.slice(colonIdx + 1) : key;
10→}
11→
12→export interface AdvisorRec {
13→  roleId: string;
14→  roleLabel: string;
15→  selection: string | null; // option label, or null if pending
16→}
17→
18→export interface RoleCard {
19→  roleId: string;
20→  roleLabel: string;
21→  playerType: "decision_maker" | "advisor";
22→  intel: string | null;
23→  decision: ActiveDecision | null;
24→  status: "intel" | "active" | "done";
25→  advisorRecs: AdvisorRec[];
26→}
27→
28→export function buildRoleCards(
29→  roles: RoleDef[],
30→  event: EventSnapshot | null,
31→  decision: ActiveDecision | null,
32→  submittedRoles: Set<string>,
33→  showDecisionMaker: boolean,
34→  allRoles?: RoleDef[],
35→): RoleCard[] {
36→  if (!event && !decision) return [];
37→  const roleLookup = allRoles ?? roles;
38→  const roleDescs = event?.role_descriptions ?? {};
39→  const targetRoles = decision?.target_roles ?? [];
40→  const allRolesTargeted = targetRoles.length === 0 && decision != null;
41→
42→  return roles
43→    .filter((role) => {
44→      if (role.player_type === "decision_maker" && !showDecisionMaker)
45→        return false;
46→      const hasIntel = roleDescs[role.id] != null;
47→      const hasDecision = allRolesTargeted || targetRoles.includes(role.id);
48→      return hasIntel || hasDecision;
49→    })
50→    .map((role) => {
51→      const hasDecision = allRolesTargeted || targetRoles.includes(role.id);
52→      const isDone = hasDecision && submittedRoles.has(role.id);
53→      const advisorRecs: AdvisorRec[] = [];
54→
55→      if (role.player_type === "decision_maker" && decision) {
56→        const advisorTargets = targetRoles.filter((rid) => rid !== role.id);
57→        for (const advisorRoleId of advisorTargets) {
58→          const advisorRole = roleLookup.find((r) => r.id === advisorRoleId);
59→          const recEntry = Object.entries(decision.recommendations || {}).find(
60→            ([key]) => extractRecRoleId(key) === advisorRoleId,
61→          );
62→          const optionId = recEntry?.[1] ?? null;
63→          const optionLabel = optionId
64→            ? (decision.options.find((o) => o.id === optionId)?.label ??
65→              optionId)
66→            : null;
67→          advisorRecs.push({
68→            roleId: advisorRoleId,
69→            roleLabel: advisorRole?.label ?? advisorRoleId,
70→            selection: optionLabel,
71→          });
72→        }
73→      }
74→
75→      const playerType =
76→        role.player_type === "decision_maker" || role.player_type === "advisor"
77→          ? role.player_type
78→          : "advisor"; // fallback — should never happen with valid scenario data
79→
80→      return {
81→        roleId: role.id,
82→        roleLabel: role.label,
83→        playerType,
84→        intel: roleDescs[role.id] ?? null,
85→        decision: hasDecision ? decision : null,
86→        status: hasDecision ? (isDone ? "done" : "active") : "intel",
87→        advisorRecs,
88→      } satisfies RoleCard;
89→    });
90→}
