 12→type SubmitEvent = {
 13→  selectedOptions: string[];
 14→  freeText: string;
 15→  targetSystemSelections: Record<string, string>;
 16→};
 17→
 18→export function buildAdvisorRecs(
 19→  decision: ActiveDecision,
 20→  roles: Pick<RoleDef, "id" | "label">[],
 21→): AdvisorRecommendation[] {
 22→  const recs = decision.recommendations || {};
 23→  return Object.entries(recs).map(([key, oid]) => {
 24→    const colonIdx = key.indexOf(":");
 25→    if (colonIdx !== -1) {
 26→      const roleId = key.slice(colonIdx + 1);
 27→      const roleInfo = roles.find((r) => r.id === roleId);
 28→      return {
 29→        participantId: key,
 30→        participantName: roleInfo?.label ?? roleId,
 31→        optionId: oid,
 32→      };
 33→    }
 34→    return { participantId: key, participantName: key, optionId: oid };
 35→  });
 36→}
 37→
 38→export function getScenarioAdvisorRoles(
 39→  roles: RoleDef[],
 40→): Pick<RoleDef, "id" | "label">[] {
 41→  return roles.filter((r) => r.player_type === "advisor");
 42→}
 43→
 44→export function submitRecommendation(
 45→  api: DecisionApiService,
 46→  exerciseId: number,
 47→  decision: ActiveDecision,
 48→  participantId: string,
 49→  event: SubmitEvent,
 50→): void {
 51→  const optionId = event.selectedOptions[0];
 52→  if (!optionId) return;
 53→  api
 54→    .submitRecommendation(exerciseId, decision.id, optionId, participantId)
 55→    .subscribe();
 56→}
 57→
 58→export function submitRoleRecommendation(
 59→  api: DecisionApiService,
 60→  exerciseId: number,
 61→  decision: ActiveDecision,
 62→  participantId: string,
 63→  rec: RoleRecommendation,
 64→): void {
 65→  const optionId = rec.selectedOptions[0];
 66→  if (!optionId) return;
 67→  api
 68→    .submitRecommendation(
 69→      exerciseId,
 70→      decision.id,
 71→      optionId,
 72→      participantId,
 73→      rec.roleId,
 74→    )
 75→    .subscribe();
 76→}
