 78→export function submitDecision(
 79→  api: DecisionApiService,
 80→  store: InstanceType<typeof ExerciseStore>,
 81→  exerciseId: number,
 82→  decision: ActiveDecision,
 83→  event: SubmitEvent,
 84→): void {
 85→  api
 86→    .closeEngineDecision(
 87→      exerciseId,
 88→      decision.id,
 89→      event.selectedOptions,
 90→      event.targetSystemSelections,
 91→    )
 92→    .subscribe({
 93→      next: () => store.closeDecision(decision.id),
 94→    });
 95→}
