 97→export function resolvePlayerRole(
 98→  ctx: ScenarioContext,
 99→  role: string,
100→  gameMode: string,
101→  store: InstanceType<typeof ExerciseStore>,
102→  roleLabel: WritableSignal<string>,
103→): void {
104→  store.setContext(ctx);
105→  if (!gameMode && ctx.roles && ctx.roles.length > 0) {
106→    store.setGameMode("simple_collaborative");
107→  }
108→  const roleInfo = ctx.roles?.find((r) => r.id === role);
109→  if (roleInfo) {
110→    store.setPlayerType(roleInfo.player_type);
111→    roleLabel.set(roleInfo.label);
112→  } else if (role === "all_advisors") {
113→    store.setPlayerType("advisor");
114→    roleLabel.set("All Advisors");
115→  } else if (role === "decision_maker") {
116→    store.setPlayerType("decision_maker");
117→    roleLabel.set("Decision Maker");
118→  } else if (role === "solo_player") {
119→    store.setPlayerType("decision_maker");
120→    roleLabel.set("Solo Player");
121→  }
122→}
